<?php

namespace App\Support;

class HelpContent
{
    public static function contextForRequest(): ?array
    {
        if (! auth()->check()) {
            return null;
        }

        $path = trim(request()->path(), '/');

        if (str_contains($path, 'help-center')) {
            return null;
        }

        foreach (self::contexts() as $needle => $context) {
            if ($needle === 'admin' ? $path === 'admin' : str_contains($path, $needle)) {
                return $context;
            }
        }

        return [
            'title' => 'Βοήθεια εφαρμογής',
            'summary' => 'Χρησιμοποιήστε το κεντρικό εγχειρίδιο για αναλυτικές οδηγίες ανά λειτουργική ενότητα.',
            'steps' => ['Εντοπίστε την ενότητα από τα περιεχόμενα.', 'Χρησιμοποιήστε την αναζήτηση με λέξεις όπως «πάγιο», «απογραφή» ή «απόσβεση».'],
            'attention' => null,
            'section' => 'getting-started',
        ];
    }

